window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-865306faf4f1ae5e"]={"versions": [{"id": "FIG-865306faf4f1ae5e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-dccdbfc1b130c271", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-eb7f2ca536aa99bc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-2a0dbbcda88ad17c", "releases": ["R4.2.2", "R4.3.1", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-fc345e5af93b4322", "releases": ["R18-10_R4.4.0_R1.5.0", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-02555155e053aee2", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}, {"id": "FIG-769302d9a5491bd5", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR BSW-Schichtenmodell / PDU-Fluss- und Architekturdiagramm (gemäß <code>AUTOSAR_SystemTemplate</code>, Release R3.2.3, Kapitel <em>Communication / System Description</em>).</li>\n<li><strong>Architektonischer Kontext:</strong> Integration eines Complex Device Drivers (CDD) in den standardisierten AUTOSAR-Kommunikations-Stack als Upper-Layer-Modul oberhalb des PDU Routers (<code>PduR</code>).</li>\n<li><strong>Funktionaler Zweck:</strong> Modellierung des Routings proprietärer, nicht durch Standard-Module (wie <code>Com</code> oder <code>Dcm</code>) verwalteter I-PDUs (<code>UserDefinedIPdu</code>). Der PDU Router entkoppelt den CDD von der konkreten Bus-Technologie (CAN, LIN, FlexRay) und leitet Datenströme wahlweise über den unsegmentierten Direktpfad (<code>Bus Interface</code>) oder über den segmentierten Pfad (<code>Bus Tp</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Schichten & Module (Top-Down)</p>\n<ol class=\"fig-list\">\n<li><strong>Communication (Services Layer):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>CDD</code> (<em>Complex Device Driver</em>): Agiert protokollseitig als Upper-Layer-Komponente (analog zu <code>Com</code> oder <code>Dcm</code>).</li>\n<li><code>PDU Router</code> (<code>PduR</code>): Zentrales Vermittlungsmodul zur statischen Weiterleitung von I-PDUs zwischen oberen und unteren BSW-Modulen.</li>\n<li><code>Bus Tp</code> (<em>Transport Protocol</em>, z. B. <code>CanTp</code>, <code>FrTp</code>, <code>LinTp</code>): BSW-Modul zur Segmentierung und Reassemblierung von Nutzdaten, die die maximale Frame-Länge der Sicherungsschicht überschreiten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication HW Abstraction:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Interface</code> (<em>Bus If</em>, z. B. <code>CanIf</code>, <code>FrIf</code>, <code>LinIf</code>): Abstrahiert Controller und Transceiver, verwaltet Tx/Rx-PDU-Handling auf Treiberebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Communication Drivers (MCAL):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Bus Driver</code> (<em>Bus Drv</em>, z. B. <code>Can</code>, <code>Fr</code>, <code>Lin</code>): Hardwarenaher Treiber mit direktem Zugriff auf die Kommunikations-Controller-Register.</li>\n</ul>\n<p class=\"fig-p\">#### PDU-Entitäten & Metamodell-Typen</p>\n<ul class=\"fig-list\">\n<li><code>UserDefinedIPdu</code> (Metamodell-Klasse: <code>AR:UserDefinedIPdu</code>, abgeleitet von <code>AR:IPdu</code>): Repräsentiert I-PDUs mit anwenderspezifischem, nicht signalinterpretiertem Payload-Format.</li>\n<li><code>N-PDU</code> (<em>Network PDU</em>): Protokolldateneinheit der Vermittlungs-/Transportschicht (PCI + fragmentierte Payload) zwischen <code>Bus Tp</code> und <code>Bus Interface</code>.</li>\n<li><code>L-PDU</code> (<em>Data Link Layer PDU</em>): Rahmen auf der Sicherungsschicht zwischen <code>Bus Interface</code> und <code>Bus Driver</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Pfadbeziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>CDD $\\leftrightarrow$ PDU Router:</strong> 1:n-Beziehung über <code>UserDefinedIPdu</code>.</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Interface (IF-Pfad):</strong> Direkter Pfad für unsegmentierte Übertragung (Payload-Größe $\\le$ L-PDU-Nutzlast).</li>\n<li><strong>PDU Router $\\leftrightarrow$ Bus Tp (TP-Pfad):</strong> Pfad für segmentierte Übertragungen (Payload-Größe > L-PDU-Nutzlast).</li>\n<li><strong>Bus Tp $\\leftrightarrow$ Bus Interface:</strong> Punkt-zu-Punkt-Kopplung auf N-PDU-Basis.</li>\n<li><strong>Bus Interface $\\leftrightarrow$ Bus Driver:</strong> Abbildung von L-PDUs auf Hardware-Mailboxen (HTH/HRH).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### A. Sendevorgang: Unsegmentierter Pfad (IF-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft synchron <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Routing:</strong> <code>PduR</code> identifiziert den Pfad anhand der konfigurierten Routing-Tabelle und delegiert synchron an <code>&lt;BusIf&gt;_Transmit(TargetPduId, PduInfoPtr)</code>.</li>\n<li><strong>Hardware-Trigger:</strong> <code>&lt;BusIf&gt;</code> übergibt die L-PDU via <code>&lt;Bus&gt;_Write(Hth, PduInfoPtr)</code> an den Treiber.</li>\n<li><strong>Tx-Confirmation:</strong> Nach erfolgreichem Bus-Versand meldet der Hardware-Interrupt: <code>&lt;Bus&gt;</code> $\\rightarrow$ <code>&lt;BusIf&gt;_TxConfirmation()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;TxConfirmation()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_TxConfirmation()</code>.</li>\n</ol>\n<p class=\"fig-p\">#### B. Sendevorgang: Segmentierter Pfad (TP-Routing)</p>\n<ol class=\"fig-list\">\n<li><strong>Trigger:</strong> <code>CDD</code> ruft <code>PduR_&lt;User&gt;Transmit(PduId, PduInfoPtr)</code> auf.</li>\n<li><strong>TP-Start:</strong> <code>PduR</code> ruft <code>&lt;BusTp&gt;_Transmit(TargetPduId, PduInfoPtr)</code> auf.</li>\n<li><strong>Data-Copy (Polling/Callback):</strong> <code>Bus Tp</code> fordert schrittweise Segmente über <code>PduR</code> an (<code>&lt;Cdd&gt;_CopyTxData()</code>).</li>\n<li><strong>Frame-Versand:</strong> Jede N-PDU wird via <code>&lt;BusIf&gt;_Transmit()</code> über den Treiber abgesetzt.</li>\n<li><strong>Abschluss:</strong> Nach Übertragung des letzten Segments quittiert <code>Bus Tp</code> via <code>PduR_&lt;BusTp&gt;TpTxConfirmation()</code> an <code>&lt;Cdd&gt;_TpTxConfirmation(Result)</code>.</li>\n</ol>\n<p class=\"fig-p\">#### C. Empfangsvorgang (Rx-Pfade)</p>\n<ul class=\"fig-list\">\n<li><strong>Direktpfad:</strong> <code>&lt;Bus&gt;_RxIndication()</code> $\\rightarrow$ <code>&lt;BusIf&gt;_RxIndication()</code> $\\rightarrow$ <code>PduR_&lt;BusIf&gt;RxIndication()</code> $\\rightarrow$ <code>&lt;Cdd&gt;_RxIndication()</code>.</li>\n<li><strong>TP-Pfad:</strong> <code>&lt;BusTp&gt;</code> detektiert <em>First Frame (FF)</em> oder <em>Single Frame (SF)</em> $\\rightarrow$ initiiert Pufferreservierung über <code>PduR</code> via <code>&lt;Cdd&gt;_StartOfReception()</code> $\\rightarrow$ fortlaufendes Pufferfüllen über <code>&lt;Cdd&gt;_CopyRxData()</code> $\\rightarrow$ finaler Callback <code>&lt;Cdd&gt;_TpRxIndication(Result)</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>PduR</code> & Metamodell):</strong></li>\n<li>In der System Description (ARXML) muss die PDU explizit als <code>UserDefinedIPdu</code> typisiert werden.</li>\n<li>Das Modul <code>PduR</code> erfordert eine <code>PduRUpperLayerConfiguration</code> für den CDD mit definierten Modul-Präfixen und zugewiesenen <code>PduRSourcePduHandleId</code> bzw. <code>PduRDestPduHandleId</code>.</li>\n<li><strong>API-Implementierungspflicht des CDD:</strong></li>\n<li>Der CDD muss zwingend die standardisierten AUTOSAR Upper-Layer-APIs bereitstellen:</li>\n<li>IF-API: <code>&lt;Cdd&gt;_RxIndication</code>, <code>&lt;Cdd&gt;_TxConfirmation</code> (und optional <code>&lt;Cdd&gt;_TriggerTransmit</code>).</li>\n<li>TP-API: <code>&lt;Cdd&gt;_StartOfReception</code>, <code>&lt;Cdd&gt;_CopyRxData</code>, <code>&lt;Cdd&gt;_CopyTxData</code>, <code>&lt;Cdd&gt;_TpRxIndication</code>, <code>&lt;Cdd&gt;_TpTxConfirmation</code>.</li>\n<li><strong>Architektonische Konsequenzen & Restriktionen:</strong></li>\n<li><strong>Kein Signal-Handling im BSW:</strong> Die Payload eines <code>UserDefinedIPdu</code> wird vom BSW-Stack als opake Byte-Sequenz behandelt; Signal-Serialisierung/-Deserialisierung und Endianness-Konvertierung müssen vollständig im CDD erfolgen.</li>\n<li><strong>Pufferlebensdauer:</strong> Bei TP-Kommunikation muss der CDD sicherstellen, dass die im <code>_CopyTxData</code>-Kontext referenzierten Puffer gültig und unverändert bleiben, bis das <code>_TpTxConfirmation</code>-Callback eintrifft.</li>\n<li><strong>Topologie-Unabhängigkeit:</strong> Durch das Vorschalten des <code>PduR</code> profitiert der CDD von PDU-Multicasting (1:n-Routing), Gateway-Fähigkeiten und Gateway-Pufferung, ohne direkten Code-Bezug zu bus-spezifischen Schnittstellen (<code>CanIf</code>, <code>FrIf</code>, etc.) herstellen zu müssen.</li>\n</ul>"}], "trans": [{"from": "FIG-865306faf4f1ae5e", "to": "FIG-dccdbfc1b130c271", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dccdbfc1b130c271", "to": "FIG-eb7f2ca536aa99bc", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eb7f2ca536aa99bc", "to": "FIG-2a0dbbcda88ad17c", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2a0dbbcda88ad17c", "to": "FIG-fc345e5af93b4322", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fc345e5af93b4322", "to": "FIG-02555155e053aee2", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-02555155e053aee2", "to": "FIG-2a0dbbcda88ad17c", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2a0dbbcda88ad17c", "to": "FIG-769302d9a5491bd5", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-769302d9a5491bd5", "to": "FIG-fc345e5af93b4322", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
